#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define FRACT_MIN .15
#define FRACT_MAX .95
#define FRACT_OFFSET 1.45

#define MAX_STEPS 40
#define MAX_DIST 60.0
#define SURFACE_DIST .001
#define inf (MAX_DIST+1.0)


float sdBox(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float sdCross(in vec3 p, float s) {
  float da = sdBox(p.xyz, vec3(1.0, s, s));
  float db = sdBox(p.yzx, vec3(s, 1.0, s));
  float dc = sdBox(p.zxy, vec3(s, s, 1.0));
  return min(da, min(db, dc));
}

vec2 rotate(vec2 p, float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c, -s, s, c)*p;
}

// modified from the fractal function found here:
// https://www.shadertoy.com/view/4XdfW4
float fractal(vec3 p, out vec3 rgb, int iterations){
  float m = 1.;
  for (int i = 0; i < iterations; i++) {
        float n = abs(p.x*p.y*p.z);
        p = abs(p)/clamp(n,FRACT_MIN,FRACT_MAX)-FRACT_OFFSET;
        m = abs(min(p.x,min(p.y,p.z)));
  }
  m = exp(-2. * m)*2.;
  rgb=vec3(1.0-p.z, p.xy) * m;
  return length(rgb);
}

float scene(vec3 p, out vec3 rgb) {
  vec2 m = iMouse.xy/iResolution.xy;
  vec3 s = p - vec3(0.0, 0.0, -15.0);
  s.xz = rotate(s.xz,m.x*-8.);
  s.xy = rotate(s.xy,m.y*-8.);
  fractal(s, rgb, 5);
  return min(10.-p.y, min(10.+p.y,min(15.0-p.x, min(15.0+p.x, sdCross(s, 3.)))));
}
float happy_star(vec2 uv, float anim)
{
    uv = abs(uv);
    vec2 pos = min(uv.xy/uv.yx, anim);
    float p = (2.0 - pos.x - pos.y);
    return (2.0+p*(p*p-1.5)) / (uv.x+uv.y);      
}

float raymarch(vec3 ro, vec3 rd, out vec3 rgb) {
  float dist = 0.0;
  for(int i = 0; i < MAX_STEPS; i++) {
    vec3 p = ro + rd * dist;
    float step = scene(p, rgb);
    dist += step;

    if(dist > MAX_DIST || step < SURFACE_DIST) {
        break;
    }
  }
  return dist;
}

vec3 getNormal(vec3 p) {
  vec2 e = vec2(.01, 0);
  vec3 rgb;
  vec3 n = scene(p, rgb) - vec3(
    scene(p-e.xyy, rgb),
    scene(p-e.yxy, rgb),
    scene(p-e.yyx, rgb));

  return normalize(n);
}
